import {summaryMarkup,editProposalInput,collectEditedProposal,summaryNeedsRefresh} from './proposal-summary.js';
import {installSetupAgent,applyAgentProposal,proposalInput} from './setup-agent.js';
import {fetchPackIndex} from './packs.js';
import {episodeDates} from './m2c.js';
import {SimulationLibrary,studioURL} from './simulation-library.js';
import {wizardDraft,stageMarkup,installStageControls,applyRegion,setupProposal,acceptSetup,goalMarkup,selectedGoals} from './setup-config.js';
import {GAS_PATH,servicesState,servicesSummary,staffingSummary,staffingBase} from './setup-utility.js';

const root=document.getElementById('setup-root'),query=new URLSearchParams(location.search);
const api=(query.get('engine')||'').replace(/\/$/,'')+'/api';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const steps=['What to test','Environment','Utility & operations','Review & open'];
const localNote='Saved in this browser. Use the same browser to return to your simulations.';
const configs=new Map();
let library,packs,draft,step=0,scenarios=[],scenarioState='idle',message='',configError='',agentOpen=false,closeAgent=null,stageControls=null,busy=false;
function alertMessage(text){const el=document.getElementById('setup-message');if(el){el.textContent=text;el.focus();}}
function save(){draft=library.save({...draft,step,wizardVersion:3});}
function capture(){if(!draft)return;for(const key of ['name','purpose','region','asOf','seed']){const input=document.getElementById('setup-'+key);if(input)draft[key]=input.value.trim();}}
function changed(dirty=true){capture();if(dirty){draft.configDirty=true;draft.agentSummaryDirty=!!draft.agentProposal;if(draft.agent)draft.agent.proposal=null;}try{save();}catch(e){alertMessage(e.message);}}
function showLibrary(){closeAgent?.();closeAgent=null;agentOpen=false;draft=null;message='';history.replaceState(null,'',location.pathname+location.search+'#/simulations');const list=library.list();
 root.innerHTML=`<section class="library"><div class="eyebrow">YOUR WORKSPACE</div><div class="library-heading"><div><h1>Your simulations</h1><p>Pick up an existing simulation, or start with a new question.</p></div><button class="primary" id="new-simulation">＋ New simulation</button></div><p class="storage-note">${localNote} Setup and analyst actions are remembered; live views are recalculated when opened.</p><p id="setup-message" role="alert" tabindex="-1"></p><div class="simulation-grid">${list.map(s=>`<article class="simulation-card"><div class="card-top"><span class="status ${s.status}">${s.status==='draft'?'SETUP IN PROGRESS':'SAVED SIMULATION'}</span><span>2026</span></div><h2>${esc(s.name||'Untitled simulation')}</h2><p>${esc(s.purpose||s.scenarioTitle||'Normal operations')}</p><dl><div><dt>Town</dt><dd>${esc(s.townName||'Not selected')}</dd></div><div><dt>Homes</dt><dd>${s.homes?Number(s.homes).toLocaleString('en-CA'):'—'}</dd></div><div><dt>View date</dt><dd>${esc(s.asOf||'—')}</dd></div></dl><button class="${s.status==='draft'?'secondary':'primary'}" data-open="${esc(s.id)}">${s.status==='draft'?'Continue setup':'Open simulation'} <span aria-hidden="true">→</span></button></article>`).join('')}</div><aside class="archive-note"><strong>Already have downloaded results?</strong><p>Open a saved run to browse its results without recalculating.</p><a href="./runs.html">Open a run folder →</a></aside></section>`;
 document.getElementById('new-simulation').onclick=()=>begin();
 root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{try{const s=library.get(b.dataset.open);if(!s)throw Error('Simulation not found in this browser.');if(s.status==='draft')begin(s);else open(s);}catch(e){alertMessage(e.message);}});
}
function begin(s){agentOpen=false;configError='';draft=wizardDraft(s||library.create(),packs);step=draft.step||0;message='';history.replaceState(null,'',location.pathname+location.search+'#/setup');render();loadConfiguration();loadScenarios();}
async function loadConfiguration(){const preset=draft?.preset;if(!preset){configError='The town catalogue could not load. Refresh to try again.';render(false);return;}if(configs.has(preset))return;
 configError='';try{const r=await fetch(api+'/setup/configuration?preset='+encodeURIComponent(preset),{signal:AbortSignal.timeout(15000)});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'Setup settings are unavailable.');configs.set(preset,data);}catch(e){configError='Could not load setup settings. '+(e.name==='TimeoutError'?'The engine took too long.':e.message);}
 if(draft?.preset===preset&&!agentOpen)render(false);
}
async function loadScenarios(){if(scenarioState==='loading'||scenarioState==='ready')return;scenarioState='loading';try{const r=await fetch(api+'/m2c/scenarios',{signal:AbortSignal.timeout(12000)});const data=await r.json();if(!r.ok||!Array.isArray(data.scenarios))throw Error();scenarios=data.scenarios;scenarioState='ready';}catch{scenarioState='failed';}if(draft&&step===2&&!agentOpen)bindScenarios();}
const starters=[['baseline','Normal operations','The usual day-to-day.'],['starter_busy','A little busy','A few more hiccups.'],['starter_pressure','Under pressure','A stretched team and rising queues.'],['starter_chaos','Organised chaos','Several things go wrong together.']];
function scenarioChoices(){return [...(draft.scenarioId==='custom'?[{id:'custom',title:draft.scenarioTitle,description:draft.summary||'Your reviewed scenario.'}]:[]),{id:'baseline',title:'Normal operations',description:'Your chosen staffing and workflow form the baseline. Add dated changes in Year.'},...scenarios.filter(s=>s.id===draft.scenarioId||draft.goals?.includes('everything')||s.id.startsWith('starter_')||s.episodes.some(ep=>Object.keys(ep.settings).some(k=>selectedGoals(configs.get(draft.preset),draft).some(g=>g.run.includes(k)))))];}
function bindScenarios(){const box=root.querySelector('#scenario-controls');if(!box)return;if(draft.goals?.length===1&&draft.goals[0]==='operations'){box.innerHTML='<p class="field-note">Use the map to inflict incidents and dispatch crews. Map-day settings above control this experiment. Year scenarios remain available from Year.</p>';return;}box.innerHTML=`<fieldset class="starter-choices"><legend>How should the year begin?</legend>${starters.map(([id,title,note],i)=>{const available=id==='baseline'||scenarios.some(s=>s.id===id);return `<label class="starter-choice ${draft.scenarioId===id?'selected':''}"><input type="radio" name="starter" value="${id}" ${draft.scenarioId===id?'checked':''} ${available?'':'disabled'}><span><small>${'●'.repeat(i+1)}${'○'.repeat(3-i)}</small><strong>${title}</strong><span>${note}</span></span></label>`;}).join('')}</fieldset><label for="setup-scenario">Or choose a specific scenario</label><select id="setup-scenario">${scenarioChoices().map(s=>`<option value="${esc(s.id)}" ${draft.scenarioId===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select><p class="field-note">${esc(scenarioChoices().find(s=>s.id===draft.scenarioId)?.description||draft.scenarioTitle)}</p>${scenarioState==='failed'?'<p class="field-note">Extra scenarios are unavailable. Normal operations is available.</p><button type="button" id="retry-scenarios" class="text-button">Retry scenarios</button>':scenarioState!=='ready'?'<p class="field-note" role="status">Loading scenarios…</p>':''}`;
 const choose=id=>{const s=scenarioChoices().find(s=>s.id===id);if(!s)return;draft.scenarioId=s.id;draft.scenarioTitle=s.title;if(id!=='custom')draft.episodes=id==='baseline'?[]:episodeDates(s,'2026-01-01').map((ep,i)=>({...ep,id:'EP-'+(i+1)}));changed();bindScenarios();};
 box.querySelector('#setup-scenario').onchange=e=>choose(e.target.value);box.querySelectorAll('[name="starter"]').forEach(i=>i.onchange=()=>choose(i.value));const retry=box.querySelector('#retry-scenarios');if(retry)retry.onclick=()=>{scenarioState='idle';loadScenarios();};
}
async function checked(proposal){const r=await fetch(api+'/setup-agent/validate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(proposalInput(proposal)),signal:AbortSignal.timeout(20000)});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:Array.isArray(data.detail)?data.detail.map(e=>e.loc.slice(1).join('.')+': '+e.msg).join('; '):'These inputs could not be accepted. Check the values.');return data.proposal;}
function lock(){busy=true;root.querySelectorAll('button,input,select,textarea').forEach(e=>e.disabled=true);alertMessage('Checking your settings…');}
async function advance(){if(busy)return;capture();if(!draft.name.trim()){alertMessage('Give your simulation a name.');return;}if(step===0){if(!draft.goals?.length){alertMessage('Choose at least one area to test.');return;}step=1;save();render();return;}if(step>0&&step<3&&stageControls?.invalid()){alertMessage('Fix the highlighted settings before continuing.');root.querySelector('[aria-invalid="true"]')?.focus();return;}if(step===3&&(draft.agentSummaryDirty||draft.configDirty)){alertMessage('Recheck the edited inputs before opening.');return;}
 lock();try{draft=acceptSetup(draft,await checked(setupProposal(draft)));if(step===3){draft.status='ready';save();open(draft);return;}step++;message='';save();}catch(e){message=e.message;}finally{busy=false;}render();
}
function reviewMarkup(){const p=draft.agentProposal,data=configs.get(draft.preset),at=(o,path)=>path.split('.').reduce((v,k)=>v?.[k],o);
 const services=servicesState({share:at(draft.townOverrides,GAS_PATH)??at(data?.defaults.town,GAS_PATH),homes:draft.homes,gasMinHomes:data?.gasDistrictMinHomes});
 return `<div class="review-name">${esc(draft.name)}</div>${draft.purpose?`<p>${esc(draft.purpose)}</p>`:''}<dl class="review"><div><dt>Test focus</dt><dd>${selectedGoals(configs.get(draft.preset),draft).map(g=>esc(g.title)).join(', ')}</dd></div><div><dt>Environment</dt><dd>${esc(draft.region||draft.townName)} · ${Number(draft.homes).toLocaleString('en-CA')} homes</dd></div><div><dt>Services</dt><dd>${esc(servicesSummary(services))}</dd></div><div><dt>Staffing</dt><dd>${esc(staffingSummary(draft.settings,staffingBase(data?.defaults.run)))}</dd></div><div><dt>Starting scenario</dt><dd>${esc(draft.scenarioTitle)}</dd></div><div><dt>Open at</dt><dd>${esc(draft.asOf)} · model year 2026</dd></div><div><dt>Run seed</dt><dd>${esc(draft.seed||'Town default')}</dd></div></dl><div class="review-edit-links"><button class="text-button" type="button" data-edit-stage="0">Edit test goals</button><button class="text-button" type="button" data-edit-stage="1">Edit environment</button><button class="text-button" type="button" data-edit-stage="2">Edit utility & operations</button><button class="text-button" id="open-agent" type="button">Refine with Claude</button></div>${p?`${summaryMarkup(p,{dirty:draft.agentSummaryDirty||draft.configDirty})}<details><summary>Assumptions and model limits</summary><ul>${[...p.assumptions,...p.limitations].map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`:''}<div class="help-card"><strong>Ready when you are.</strong><p>Your simulation opens in ${draft.goals?.length===1&&draft.goals[0]==='operations'?'the operations map':'Year'}. It keeps its own settings and analyst actions. You can return to Config to refine it.</p></div>`;}
function render(focus=true){if(!draft)return;if(summaryNeedsRefresh(draft.agentProposal))draft.agentSummaryDirty=true;closeAgent?.();closeAgent=null;stageControls=null;
 if(agentOpen){root.innerHTML='<section class="wizard agent-wizard"><aside class="wizard-rail"><div class="eyebrow">CONVERSATIONAL SETUP</div><h2>Your environment.<br>Your utility.</h2><p>Start with what to test, then focus on the environment and operations that matter.</p><div class="rail-foot">You review every input before opening Year.</div></aside><section class="wizard-panel" id="agent-root"></section></section>';
  closeAgent=installSetupAgent({root:document.getElementById('agent-root'),api,getDraft:()=>draft,onSave:agent=>{draft.agent=agent;draft.name||='Untitled simulation';save();},onApply:p=>{draft=applyAgentProposal(draft,p);draft.environmentProfile='custom';draft.agentSummaryDirty=false;draft.configDirty=false;step=3;save();agentOpen=false;render();loadConfiguration();},onBack:()=>{agentOpen=false;render();loadConfiguration();}});return;}
 const data=configs.get(draft.preset),agentEntry='<aside class="agent-entry"><div><strong>Prefer to talk it through?</strong><p>Describe the question you want to answer. Claude can help choose the relevant settings.</p></div><button class="secondary" type="button" id="open-agent">Talk it through →</button></aside>';
 const configPart=configError?`<p class="inline-error">${esc(configError)}</p><button type="button" class="secondary" id="retry-config">Retry settings</button>`:`<p class="focus-note">Focus: ${selectedGoals(data,draft).map(g=>esc(g.title)).join(', ')||'Choose what to test first'}. Advanced includes the relevant settings and an option to show everything.</p>${stageMarkup(step-1,data,draft)}`;
 const content=step===0?`${agentEntry}<label for="setup-name">Simulation name</label><input id="setup-name" value="${esc(draft.name)}" maxlength="100" placeholder="e.g. Can our VEE team handle a busier winter?" required autocomplete="off">${data?goalMarkup(data,draft):configPart}<label for="setup-purpose">What would a useful result tell you? <span>Optional</span></label><textarea id="setup-purpose" maxlength="500" rows="2" placeholder="e.g. How many analysts do we need to clear the backlog?">${esc(draft.purpose)}</textarea>`:step===1?`${agentEntry}${configPart}`:step===2?`${agentEntry}${configPart}<div class="setup-section"><div id="scenario-controls"></div><label for="setup-asOf">Open at this date</label><input id="setup-asOf" type="date" min="2026-01-01" max="2026-12-31" value="${esc(draft.asOf)}" required><p class="field-note">The model starts January 1, 2026. Starting scenarios add dated changes to the baseline you chose above.</p><details><summary>Repeatability</summary><label for="setup-seed">Run seed <span>Optional</span></label><input id="setup-seed" maxlength="64" value="${esc(draft.seed)}" placeholder="Use the town’s seed"><p class="field-note">The environment’s master seed shapes the town. This optional seed re-rolls the utility year.</p></details></div>`:reviewMarkup();
 const headings=['What do we really want to test?','Build the environment.','Set up your utility.','Your simulation, ready to open.'];
 const intros=['Choose your experiment. We’ll tailor the next pages to the parts of the engine you care about.','Choose the size and regional character of the place you want to model.','Choose services, staffing and how the year begins.','Review what each input changes. Edit a value here or return to either setup stage.'];
 root.innerHTML=`<div class="wizard"><aside class="wizard-rail"><div class="eyebrow">NEW SIMULATION</div><h2>A place.<br>A utility.<br>A year to explore.</h2><p>Start with the essentials. Open Advanced whenever you want more control.</p><ol>${steps.map((title,i)=>`<li class="${i===step?'current':i<step?'complete':''}" ${i===step?'aria-current="step"':''}><span>${i<step?'✓':i+1}</span>${title}</li>`).join('')}</ol><div class="rail-foot">Your setup is saved as you go.<br>No account needed.</div></aside><section class="wizard-panel"><div class="wizard-top"><span>STEP ${step+1} OF 4</span><button class="text-button" type="button" id="show-library">My simulations</button></div><h1 tabindex="-1">${headings[step]}</h1><p class="intro">${intros[step]}</p><form id="setup-form">${content}<p id="setup-message" role="alert" tabindex="-1">${esc(message)}</p><div class="wizard-actions"><button class="secondary" id="previous" type="button" ${step===0?'hidden':''}>← Back</button><span></span><button class="primary" type="submit" ${step<3&&!data?'disabled':''}>${step===3?'Open simulation':step===0?'Choose environment':step===1?'Continue to utility':'Review setup'} <span aria-hidden="true">→</span></button></div></form><p class="storage-note">${localNote}</p></section></div>`;
 if(step>0&&step<3&&data&&!configError)stageControls=installStageControls({root,stage:step-1,data,getDraft:()=>draft,onChange:changed,onShowAll:show=>{(draft.showAllSettings||={})[step-1]=show;save();render(false);},onError:alertMessage,getOperationDefaults:async()=>{const r=await fetch(api+'/setup/operation-defaults',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'Setup defaults',summary:'Resolve inherited map settings',preset:draft.preset,townOverrides:draft.townOverrides}),signal:AbortSignal.timeout(15000)});const result=await r.json();if(!r.ok)throw Error(typeof result.detail==='string'?result.detail:'Check the town settings.');return result.defaults;},onRegion:region=>{capture();draft=region?applyRegion(draft,region):{...draft,environmentProfile:'custom'};root.querySelector('#setup-region').value=draft.region||'';changed();render(false);}});
 root.querySelectorAll('[name="test-goal"]').forEach(input=>input.onchange=()=>{const goals=new Set(draft.goals||[]);if(input.checked){if(input.value==='everything')goals.clear();else goals.delete('everything');goals.add(input.value);}else goals.delete(input.value);draft.goals=[...goals];draft.showAllSettings={};changed();root.querySelectorAll('[name="test-goal"]').forEach(i=>i.checked=goals.has(i.value));});
 if(step===2)bindScenarios();
 if(focus)root.querySelector('h1').focus();
 const submit=root.querySelector('#setup-form button[type="submit"]');if(step===3)submit.disabled=!!(draft.agentSummaryDirty||draft.configDirty);
 const summaryCheck=root.querySelector('[data-summary-recheck]');if(summaryCheck){root.querySelectorAll('[data-summary-change]').forEach(input=>input.oninput=()=>{draft.agentSummaryDirty=true;draft.configDirty=true;try{draft.agentProposal=editProposalInput(draft.agentProposal,Number(input.dataset.summaryChange),input.value);}catch{}save();submit.disabled=true;summaryCheck.hidden=false;root.querySelector('.summary-status').textContent='Edits need checking. Recheck the summary before opening.';});
  summaryCheck.onclick=async()=>{let candidate;try{candidate=collectEditedProposal(draft.agentProposal,root);}catch(e){alertMessage(e.message);return;}lock();try{draft=acceptSetup(draft,await checked(candidate));if(draft.agent)draft.agent.proposal=null;save();message='Inputs checked. Review their updated effects below.';}catch(e){message=e.message;}busy=false;render(false);};}
 const agentButton=root.querySelector('#open-agent');if(agentButton)agentButton.onclick=()=>{capture();if(step===3&&(draft.agentSummaryDirty||draft.configDirty)){alertMessage('Recheck the summary edits before switching to the conversation.');return;}if(stageControls?.invalid()){alertMessage('Fix the highlighted settings before switching to the conversation.');return;}agentOpen=true;render();};
 root.querySelector('#show-library').onclick=()=>{try{capture();if(draft.name)save();showLibrary();}catch(e){alertMessage(e.message);}};
 root.querySelector('#previous').onclick=()=>{if(step===3&&(draft.agentSummaryDirty||draft.configDirty)){alertMessage('Recheck the summary edits before switching stages.');return;}if(stageControls?.invalid()){alertMessage('Fix the highlighted settings before going back.');return;}capture();step--;message='';save();render();};
 root.querySelectorAll('[data-edit-stage]').forEach(b=>b.onclick=()=>{if(draft.agentSummaryDirty||draft.configDirty){alertMessage('Recheck the summary edits before switching stages.');return;}step=Number(b.dataset.editStage);save();render();});
 root.querySelector('#setup-form').onsubmit=e=>{e.preventDefault();advance();};
 for(const key of ['name','purpose','region','asOf','seed']){const input=root.querySelector('#setup-'+key);if(input)input.oninput=()=>changed();}
 const retry=root.querySelector('#retry-config');if(retry)retry.onclick=()=>loadConfiguration();
}
function open(s){library.update(s.id,{openedAt:new Date().toISOString()});location.href=studioURL(s,location.search);}
try{library=new SimulationLibrary();packs=await fetchPackIndex();library.adoptPacks(packs);if(library.list().length)showLibrary();else begin();}
catch(e){root.innerHTML=`<section class="library"><h1>Your simulations couldn’t open.</h1><p role="alert">${esc(e.message)}</p><button class="primary" onclick="location.reload()">Try again</button><p>Existing browser data has not been removed.</p></section>`;}
